concepts.body:
A **message** is a typed record, like a paper form with labelled boxes. Each box is a **field**, and every field has a type, a name and a **field number**:

```protobuf
message User {
  int64 id = 1;
  string email = 2;
  repeated string roles = 3;
  map<string, string> labels = 4;
  Status status = 5;
  optional string nickname = 6;
}
enum Status { STATUS_UNSPECIFIED = 0; STATUS_ACTIVE = 1; }
```

Key rules in proto3, the current version of the format:

- The **field number**, not the name, identifies a field in the encoded bytes. Numbers 1 to 15 take one byte to encode, so give them to frequent fields. Never change a number once it's in use.
- Basic single-value types, called **scalars**, include `int32` and `int64` (whole numbers), `uint32` (never negative), `sint64` (efficient for negative numbers), `double` (decimals), `bool`, `string` (text) and `bytes`.
- Unset fields read as **default values** (0, "", false, the first enum value). Without `optional`, you can't tell "unset" from "set to the default"; with `optional` you can (`has_` methods, or `undefined` in JS).
- `repeated` makes a list; `map<K, V>` makes a set of key-value pairs, in no particular order.
- An **enum** is a type with a fixed set of named values, like `STATUS_ACTIVE`. Enums must start with a zero value, by convention `X_UNSPECIFIED = 0`.

Messages can contain other messages. Use `package` to give your types a family name (`shop.v1.Order`) so they don't clash with anyone else's, and `import` other .proto files, including Google's **well-known types** such as `google.protobuf.Timestamp` (a moment in time) and `Duration` (a length of time).

concepts.code:
syntax = "proto3";
package shop.v1;

import "google/protobuf/timestamp.proto";

message Order {
  string id = 1;
  repeated LineItem items = 2;
  OrderStatus status = 3;
  google.protobuf.Timestamp created_at = 4;
  optional string coupon = 5;     // presence: unset vs ""
  map<string, string> labels = 6;
}

message LineItem {
  string sku = 1;
  int32 quantity = 2;
  int64 price_cents = 3;          // money as integer cents
}

enum OrderStatus {
  ORDER_STATUS_UNSPECIFIED = 0;
  ORDER_STATUS_PAID = 1;
  ORDER_STATUS_SHIPPED = 2;
}

syntax = "proto3";
package chat.v1;

service ChatService {
  // unary
  rpc GetRoom(GetRoomRequest) returns (GetRoomResponse);
  // server streaming: one request, many messages
  rpc WatchRoom(WatchRoomRequest) returns (stream RoomEvent);
  // client streaming: many requests, one response
  rpc UploadHistory(stream HistoryChunk) returns (UploadHistoryResponse);
  // bidirectional streaming
  rpc Chat(stream ChatMessage) returns (stream ChatMessage);
}

message GetRoomRequest { string room_id = 1; }
message GetRoomResponse { string name = 1; int32 members = 2; }
message WatchRoomRequest { string room_id = 1; }
message RoomEvent { string text = 1; }
message HistoryChunk { bytes data = 1; }
message UploadHistoryResponse { int64 bytes_received = 1; }
message ChatMessage { string from = 1; string text = 2; }

// hello.proto: service Greeter { rpc SayHello (HelloRequest) returns (HelloReply); }
//              message HelloRequest { string name = 1; }  message HelloReply { string message = 1; }
import * as grpc from "@grpc/grpc-js";
import * as protoLoader from "@grpc/proto-loader";

const def = protoLoader.loadSync("hello.proto", { keepCase: true, defaults: true });
const { hello } = grpc.loadPackageDefinition(def);

const server = new grpc.Server();
server.addService(hello.v1.Greeter.service, {
  SayHello: (call, callback) => callback(null, { message: `Hello, ${call.request.name}` }),
});
server.bindAsync("127.0.0.1:50051", grpc.ServerCredentials.createInsecure(), (err) => {
  if (err) throw err;
  const client = new hello.v1.Greeter("127.0.0.1:50051", grpc.credentials.createInsecure());
  client.SayHello({ name: "Ann" }, (err, reply) => {
    console.log(reply.message); // Hello, Ann
    client.close();
    server.forceShutdown();
  });
});

import * as grpc from "@grpc/grpc-js";
import * as protoLoader from "@grpc/proto-loader";
const { hello } = grpc.loadPackageDefinition(protoLoader.loadSync("hello.proto"));

const server = new grpc.Server();
server.addService(hello.v1.Greeter.service, {
  SayHello: ({ request }, callback) => {
    if (!request.name) {
      return callback({ code: grpc.status.INVALID_ARGUMENT, details: "name is required" });
    }
    callback(null, { message: `Hello, ${request.name}` });
  },
});
server.bindAsync("127.0.0.1:50052", grpc.ServerCredentials.createInsecure(), () => {
  const client = new hello.v1.Greeter("127.0.0.1:50052", grpc.credentials.createInsecure());
  client.SayHello({ name: "" }, (err) => {
    console.log(err.code, grpc.status[err.code], err.details);
    // 3 INVALID_ARGUMENT name is required
    server.forceShutdown();
  });
});

// hello.proto adds: rpc CountDown (CountRequest) returns (stream Tick);
//   message CountRequest { int32 from = 1; }  message Tick { int32 n = 1; }
import * as grpc from "@grpc/grpc-js";
import * as protoLoader from "@grpc/proto-loader";
const { hello } = grpc.loadPackageDefinition(protoLoader.loadSync("hello.proto"));

const server = new grpc.Server();
server.addService(hello.v1.Greeter.service, {
  CountDown: (call) => {
    for (let n = call.request.from; n > 0; n--) call.write({ n });
    call.end();
  },
});
server.bindAsync("127.0.0.1:50053", grpc.ServerCredentials.createInsecure(), async () => {
  const client = new hello.v1.Greeter("127.0.0.1:50053", grpc.credentials.createInsecure());
  const ticks = [];
  for await (const tick of client.CountDown({ from: 3 })) ticks.push(tick.n);
  console.log(ticks); // [ 3, 2, 1 ]
  server.forceShutdown();
});

import * as grpc from "@grpc/grpc-js";
import * as protoLoader from "@grpc/proto-loader";
const { hello } = grpc.loadPackageDefinition(protoLoader.loadSync("hello.proto"));

const server = new grpc.Server();
server.addService(hello.v1.Greeter.service, {
  SayHello: (call, callback) => {
    const timer = setTimeout(() => callback(null, { message: "late" }), 2000);
    call.on("cancelled", () => { clearTimeout(timer); console.log("server: cancelled"); });
  },
});
server.bindAsync("127.0.0.1:50054", grpc.ServerCredentials.createInsecure(), () => {
  const client = new hello.v1.Greeter("127.0.0.1:50054", grpc.credentials.createInsecure());
  client.SayHello({ name: "Ann" }, { deadline: Date.now() + 200 }, (err) => {
    console.log("client:", grpc.status[err.code]); // client: DEADLINE_EXCEEDED
    setTimeout(() => server.forceShutdown(), 100);
  });
});
// also printed: server: cancelled

import * as grpc from "@grpc/grpc-js";
import * as protoLoader from "@grpc/proto-loader";
const { hello } = grpc.loadPackageDefinition(protoLoader.loadSync("hello.proto"));

const server = new grpc.Server();
server.addService(hello.v1.Greeter.service, {
  SayHello: (call, callback) => {
    const [auth] = call.metadata.get("authorization");
    if (auth !== "Bearer s3cret") {
      return callback({ code: grpc.status.UNAUTHENTICATED, details: "bad token" });
    }
    callback(null, { message: `Hello, ${call.request.name}` });
  },
});
server.bindAsync("127.0.0.1:50055", grpc.ServerCredentials.createInsecure(), () => {
  const client = new hello.v1.Greeter("127.0.0.1:50055", grpc.credentials.createInsecure());
  const md = new grpc.Metadata();
  md.set("authorization", "Bearer s3cret");
  client.SayHello({ name: "Ann" }, md, (err, reply) => {
    console.log(reply.message); // Hello, Ann
    server.forceShutdown();
  });
});

