import * as grpc from "@grpc/grpc-js";
import * as protoLoader from "@grpc/proto-loader";
const { hello } = grpc.loadPackageDefinition(protoLoader.loadSync("hello.proto"));

// Client interceptor: add a request id and log the final status
const requestId = (options, nextCall) =>
  new grpc.InterceptingCall(nextCall(options), {
    start(metadata, listener, next) {
      metadata.set("x-request-id", "req-42");
      next(metadata, {
        onReceiveStatus(status, nextStatus) {
          console.log(options.method_definition.path, grpc.status[status.code]);
          nextStatus(status);
        },
      });
    },
  });
const server = new grpc.Server();
server.addService(hello.v1.Greeter.service, {
  SayHello: (call, cb) => cb(null, { message: call.metadata.get("x-request-id")[0] }),
});
server.bindAsync("127.0.0.1:50056", grpc.ServerCredentials.createInsecure(), () => {
  const client = new hello.v1.Greeter("127.0.0.1:50056", grpc.credentials.createInsecure(), { interceptors: [requestId] });
  client.SayHello({ name: "Ann" }, (err, r) => { console.log(r.message); server.forceShutdown(); });
}); // prints: /hello.v1.Greeter/SayHello OK, then req-42

import * as grpc from "@grpc/grpc-js";
import * as protoLoader from "@grpc/proto-loader";
const { hello } = grpc.loadPackageDefinition(protoLoader.loadSync("hello.proto"));

// Client-side round robin over every address DNS returns
const client = new hello.v1.Greeter(
  "dns:///greeter.default.svc.cluster.local:50051", // headless service
  grpc.credentials.createInsecure(),
  {
    "grpc.service_config": JSON.stringify({ loadBalancingConfig: [{ round_robin: {} }] }),
    "grpc.keepalive_time_ms": 30_000,     // ping after 30 s idle
    "grpc.keepalive_timeout_ms": 10_000,  // drop if no ack in 10 s
  },
);

// Server: make clients reconnect every 5 minutes to rebalance
const server = new grpc.Server({
  "grpc.max_connection_age_ms": 5 * 60_000,
  "grpc.keepalive_permit_without_calls": 1,
});
console.log(typeof client.SayHello, typeof server.addService); // function function

syntax = "proto3";
package users.v1;

import "google/api/annotations.proto";

service UserService {
  rpc GetUser(GetUserRequest) returns (User) {
    option (google.api.http) = { get: "/v1/users/{id}" };
  }
  rpc CreateUser(CreateUserRequest) returns (User) {
    option (google.api.http) = { post: "/v1/users" body: "user" };
  }
}

message GetUserRequest { string id = 1; }
message CreateUserRequest { User user = 1; }
message User { string id = 1; string display_name = 2; int64 karma = 3; }

// GET /v1/users/42 via a transcoding gateway returns canonical JSON:
// { "id": "42", "displayName": "Ann", "karma": "1200" }  <- int64 as string

// Hand-encode HelloRequest { name: "Ann" } and frame it like gRPC does
const name = Buffer.from("Ann", "utf8");
const key = (1 << 3) | 2;                          // field 1, wire type 2 (LEN)
const msg = Buffer.concat([Buffer.from([key, name.length]), name]);
console.log(msg.toString("hex"));                  // 0a03416e6e

const frame = Buffer.alloc(5 + msg.length);
frame.writeUInt8(0, 0);                            // not compressed
frame.writeUInt32BE(msg.length, 1);                // 4-byte length
msg.copy(frame, 5);
console.log(frame.toString("hex"));                // 00000000050a03416e6e

// varint of 300: 7 bits per byte, low group first
const varint = (n) => { const out = []; do { let b = n & 0x7f; n >>>= 7; if (n) b |= 0x80; out.push(b); } while (n); return Buffer.from(out); };
console.log(varint(300).toString("hex"));          // ac02

// Service config JSON, passed as the grpc.service_config channel option
const serviceConfig = {
  loadBalancingConfig: [{ round_robin: {} }],
  methodConfig: [
    {
      name: [{ service: "hello.v1.Greeter", method: "SayHello" }],
      timeout: "0.5s",                // default deadline per call
      retryPolicy: {
        maxAttempts: 4,
        initialBackoff: "0.1s",
        maxBackoff: "1s",
        backoffMultiplier: 2,
        retryableStatusCodes: ["UNAVAILABLE"],
      },
    },
  ],
  retryThrottling: { maxTokens: 10, tokenRatio: 0.1 },
};
const options = { "grpc.service_config": JSON.stringify(serviceConfig) };
console.log(Object.keys(options)); // [ 'grpc.service_config' ]
// new hello.v1.Greeter(target, credentials, options)

import * as grpc from "@grpc/grpc-js";

// Channel options for a high-throughput internal client
const options = {
  "grpc.max_receive_message_length": 8 * 1024 * 1024, // 8 MB instead of 4 MB
  "grpc.max_send_message_length": 8 * 1024 * 1024,
  "grpc.default_compression_algorithm": 2,             // 2 = gzip
  "grpc.keepalive_time_ms": 60_000,
};

// Server side: cap concurrent streams per connection
const server = new grpc.Server({ "grpc.max_concurrent_streams": 200 });
console.log(Object.keys(options).length, typeof server.bindAsync); // 4 function

